package com.bank.settlement.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Rearranges an array of 0s (failed) and 1s (cleared) in place: all 0s first.
public class OutcomeSegregator {
    private static final Logger log = Logger.getLogger(OutcomeSegregator.class.getName());

    // In-place, single pass, O(1) extra space.
    public void segregate(int[] outcomes) {
        if (outcomes == null || outcomes.length < 2) {
            log.fine("Nothing to segregate.");
            return;
        }
        int low = 0; // next position where a 0 should land
        for (int i = 0; i < outcomes.length; i++) {
            if (outcomes[i] == 0) {
                swap(outcomes, i, low);
                low++;
            }
        }
        log.info(() -> "Segregated batch: " + Arrays.toString(outcomes)
                + " (" + low + " failed grouped at front)");
    }

    private void swap(int[] a, int i, int j) {
        if (i == j) return; // swapping with itself is a no-op
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }
}
