package com.bank.settlement;

import com.bank.settlement.service.OutcomeSegregator;
import java.util.Arrays;
import java.util.logging.Logger;

public class SegregatorDemo {
    private static final Logger log = Logger.getLogger(SegregatorDemo.class.getName());

    public static void main(String[] args) {
        // 0 = failed settlement, 1 = cleared settlement.
        int[] outcomes = {1, 0, 1, 0, 0, 1};
        log.info(() -> "Before: " + Arrays.toString(outcomes));

        OutcomeSegregator segregator = new OutcomeSegregator();
        segregator.segregate(outcomes);

        log.info(() -> "After:  " + Arrays.toString(outcomes));
    }
}
